"""Editorially paired expressions and notation; not two positional lists."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Formula:
    expression: str
    notation: str
    conditions: str


def f(expression: str, notation: str, conditions: str) -> Formula:
    return Formula(expression, notation, conditions)


